import {
  SegmentGroup as SegmentGroupPrimitive,
  useSegmentGroup as useSegmentGroupPrimitive,
  useSegmentGroupContext,
  useSegmentGroupItemContext,
  type UseSegmentGroupProps,
} from '@ark-ui/solid/segment-group';
import { clsx } from 'clsx';
import type { ComponentProps, JSX } from 'solid-js';
import { For, splitProps } from 'solid-js';
import styles from './SegmentGroup.module.css';

type SegmentGroupMachineProps = NonNullable<Parameters<typeof useSegmentGroupPrimitive>[0]>;
type SegmentGroupOption = {
  value: string;
  label: JSX.Element;
  disabled?: boolean;
};

function useSegmentGroup(props?: SegmentGroupMachineProps) {
  return useSegmentGroupPrimitive(() => {
    const machineProps: UseSegmentGroupProps =
      (typeof props === 'function' ? props() : props) ?? {};
    return { ...machineProps, orientation: machineProps.orientation ?? 'horizontal' };
  });
}

function SegmentGroup(props: ComponentProps<typeof SegmentGroupPrimitive.Root>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SegmentGroupPrimitive.Root
      orientation="horizontal"
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="segment-group-root"
    />
  );
}

function SegmentGroupRootProvider(
  props: ComponentProps<typeof SegmentGroupPrimitive.RootProvider>,
) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SegmentGroupPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="segment-group-root-provider"
    />
  );
}

function SegmentGroupLabel(props: ComponentProps<typeof SegmentGroupPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SegmentGroupPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="segment-group-label"
    />
  );
}

function SegmentGroupItem(props: ComponentProps<typeof SegmentGroupPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SegmentGroupPrimitive.Item
      class={clsx(styles.item, local.class)}
      {...others}
      data-slot="segment-group-item"
    />
  );
}

function SegmentGroupItemText(props: ComponentProps<typeof SegmentGroupPrimitive.ItemText>) {
  return <SegmentGroupPrimitive.ItemText {...props} data-slot="segment-group-item-text" />;
}

function SegmentGroupIndicator(props: ComponentProps<typeof SegmentGroupPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SegmentGroupPrimitive.Indicator
      class={clsx(styles.indicator, local.class)}
      {...others}
      data-slot="segment-group-indicator"
    />
  );
}

const SegmentGroupContext = SegmentGroupPrimitive.Context;
const SegmentGroupItemContext = SegmentGroupPrimitive.ItemContext;
const SegmentGroupItemHiddenInput = SegmentGroupPrimitive.ItemHiddenInput;

function SegmentGroupItems(props: { items: readonly SegmentGroupOption[] }) {
  return (
    <For each={props.items}>
      {(item) => (
        <SegmentGroupItem value={item.value} disabled={item.disabled}>
          <SegmentGroupItemText>{item.label}</SegmentGroupItemText>
          <SegmentGroupItemHiddenInput />
        </SegmentGroupItem>
      )}
    </For>
  );
}

export {
  SegmentGroup,
  SegmentGroupContext,
  SegmentGroupIndicator,
  SegmentGroupItem,
  SegmentGroupItemContext,
  SegmentGroupItemHiddenInput,
  SegmentGroupItems,
  SegmentGroupItemText,
  SegmentGroupLabel,
  SegmentGroupRootProvider,
  useSegmentGroup,
  useSegmentGroupContext,
  useSegmentGroupItemContext,
};

@layer moduix.components {
  .root {
    box-sizing: border-box;
    isolation: isolate;
    display: inline-flex;
    max-inline-size: 100%;
    gap: var(--moduix-spacing-1);
    padding: var(--moduix-spacing-1);
    border: var(--moduix-border-width-sm) solid
      var(--moduix-segment-group-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-segment-group-bg, var(--moduix-color-muted));
    color: var(--moduix-color-foreground);

    &[data-orientation='vertical'] {
      flex-direction: column;
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }

    &:not([data-disabled]) .item[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);
    }
  }

  .label {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-sm);
  }

  .item {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-spacing-2);
    min-height: var(--moduix-size-sm);
    padding-inline: var(--moduix-spacing-3-5);
    border-radius: var(--moduix-radius-md);
    color: var(--moduix-segment-group-item-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    white-space: nowrap;
    user-select: none;
    cursor: pointer;
    transition: color var(--moduix-transition-default);

    &[data-state='checked'] {
      color: var(--moduix-segment-group-item-color-checked, var(--moduix-color-foreground));
    }

    @media (hover: hover) {
      &[data-state='unchecked']:hover:not([data-readonly], [data-disabled]) {
        color: var(--moduix-color-foreground);
      }
    }

    &[data-focus-visible] {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-border-width-sm);
    }

    &[data-invalid] {
      outline-color: var(--moduix-color-destructive);
    }

    &[data-disabled],
    &[data-readonly] {
      cursor: default;
    }

    &[data-orientation='vertical'] {
      justify-content: flex-start;
    }
  }

  .indicator {
    --transition-duration: var(--moduix-duration-normal);
    --transition-timing-function: var(--moduix-ease-in-out);

    z-index: -1;
    top: var(--top);
    left: var(--left);
    width: var(--width);
    height: var(--height);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-segment-group-indicator-bg, var(--moduix-color-background));
    box-shadow: var(--moduix-shadow-sm);
    pointer-events: none;
  }
}
